import { defineConfig, devices } from '@playwright/test'

/**
 * The line baselines again, in WebKit on an iPhone: the engine that actually
 * draws the globe on phones. Chrome's software GL cannot show what iOS does
 * with a transparent canvas, so a line defect that only appears there (a
 * solid white band instead of a thin glow) is invisible to the Chrome gate.
 *
 * Runs in Playwright's container (it has WebKit and its libraries). The PNGs
 * are generated by the "Update visual baselines" workflow, never locally.
 */
const PORT = 4173

export default defineConfig({
  testDir: './playwright-tests/visual',
  testMatch: 'lines.spec.ts',
  // Phones only: that is where the lines went wrong.
  grep: /phone/,
  workers: 1,
  fullyParallel: false,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  timeout: 120_000,
  expect: {
    timeout: 30_000,
    toHaveScreenshot: {
      maxDiffPixelRatio: 0.004,
      threshold: 0.2,
      animations: 'disabled',
      caret: 'hide',
      scale: 'css',
    },
  },
  snapshotPathTemplate: '{testDir}/__screenshots__/webkit/{arg}{ext}',
  outputDir: 'test-results/visual-webkit',
  reporter: process.env.CI
    ? [
        ['list'],
        [
          'html',
          { open: 'never', outputFolder: 'playwright-report/visual-webkit' },
        ],
      ]
    : [['list']],
  use: {
    baseURL: `http://127.0.0.1:${PORT}`,
    trace: 'retain-on-failure',
    serviceWorkers: 'block',
  },
  projects: [{ name: 'visual-webkit', use: { ...devices['iPhone 12'] } }],
  webServer: {
    command: `npx vite build && npx vite preview --port ${PORT} --strictPort --host 127.0.0.1`,
    url: `http://127.0.0.1:${PORT}`,
    reuseExistingServer: !process.env.CI,
    timeout: 240_000,
  },
})
